corrected_code:
const resolvers = {
  Query: {
    paymentMethod: async (_, args, context) => {
      const pm = await PaymentMethod.findByPk(args.id);
      if (pm && pm.userId !== context.user.id) throw new Error('Unauthorized');
      return pm;
    }
  }
};
